import{_ as t,c as o,o as a,ae as i}from"./chunks/framework.CliRSA9F.js";const u=JSON.parse('{"title":"Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"features/notifications.md","filePath":"features/notifications.md"}'),s={name:"features/notifications.md"};function n(r,e,l,h,c,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h1><h2 id="stay-informed-about-important-changes" tabindex="-1">Stay Informed About Important Changes <a class="header-anchor" href="#stay-informed-about-important-changes" aria-label="Permalink to &quot;Stay Informed About Important Changes&quot;">​</a></h2><p>Notifications keep you up to date on significant events related to your podcast — chart appearances, editorial features, PR mentions, competitor activity, trend alerts, podcast health, social clips and posts, and more. Instead of checking every section manually, notifications bring the most important updates to you.</p><p><strong>To access</strong>: Click <strong>Notifications</strong> in the sidebar.</p><h2 id="what-gets-notified" tabindex="-1"><strong>What Gets Notified</strong> <a class="header-anchor" href="#what-gets-notified" aria-label="Permalink to &quot;**What Gets Notified**&quot;">​</a></h2><p>PodSEO sends notifications for events that are likely to require your attention.</p><p><strong>Your podcast&#39;s wins and health</strong></p><ul><li><strong>Chart appearances</strong> — When your podcast enters a platform chart</li><li><strong>Editorial features</strong> — When your podcast is added to a curated or editorial list</li><li><strong>PR mentions</strong> — When your podcast is picked up by a new PR or media source</li><li><strong>New-episode insight</strong> — A short read on how your newest episode is set up for discovery (paid plans)</li><li><strong>Podcast health check</strong> — A periodic summary of your show&#39;s distribution and feed health</li><li><strong>Podcast health alert</strong> — An urgent alert when your feed stops working or your show is removed from a listening platform</li></ul><p><strong>Competitors</strong></p><ul><li><strong>Competitor activity</strong> — New chart appearances, editorial lists, and PR mentions for podcasts you&#39;re tracking</li></ul><p><strong>Trends</strong></p><ul><li><strong>Pulse news</strong> — News stories relevant to your podcast&#39;s niche</li><li><strong>Pulse Google Trends ideas</strong> — Trending Google searches that match your keywords, as timely episode ideas</li></ul><p><strong>Social Publishing</strong></p><ul><li><strong>Clip highlights ready</strong> — When PodSEO has found the best moments in an episode for social clips</li><li><strong>Clip video ready</strong> — When a new social clip has finished generating</li><li><strong>Social post results</strong> — Whether your scheduled or published posts went out successfully</li><li><strong>Social account needs reconnecting</strong> — When a connected social account needs to be reconnected before PodSEO can post to it</li></ul><p><strong>Your account</strong></p><ul><li><strong>Monthly credits refreshed</strong> — When your monthly credit allowance resets</li><li><strong>Plan changes</strong> — When your subscription changes</li><li><strong>Announcements</strong> — Important updates about PodSEO features</li></ul><h2 id="the-notifications-page" tabindex="-1"><strong>The Notifications Page</strong> <a class="header-anchor" href="#the-notifications-page" aria-label="Permalink to &quot;**The Notifications Page**&quot;">​</a></h2><p>The Notifications page lists your full notification history across all your podcasts. Switch between <strong>Unread</strong> and <strong>All</strong>, and use the podcast filter to focus on a single show. Click <strong>Mark all read</strong> to clear your unread notifications (when a podcast filter is applied, the button marks just that podcast&#39;s notifications as read).</p><h2 id="your-weekly-email" tabindex="-1"><strong>Your Weekly Email</strong> <a class="header-anchor" href="#your-weekly-email" aria-label="Permalink to &quot;**Your Weekly Email**&quot;">​</a></h2><p>Every Monday, PodSEO sends one weekly email that brings everything together. It includes a keyword ranking scorecard — your ranking improvements, declines, new keyword rankings, and keywords close to the top five — alongside the notifications from that week that you&#39;ve set to the weekly digest. The ranking section appears when you&#39;re tracking keywords and have been active in PodSEO recently; if it was a quiet week, the email suggests reviewing your rankings.</p><h2 id="managing-notifications" tabindex="-1"><strong>Managing Notifications</strong> <a class="header-anchor" href="#managing-notifications" aria-label="Permalink to &quot;**Managing Notifications**&quot;">​</a></h2><p>You can configure which notifications you receive and how you receive them from <strong>Settings → Notifications</strong>. This lets you focus on the signals that matter most to your workflow without being overwhelmed by updates.</p><h2 id="integration-with-other-features" tabindex="-1"><strong>Integration with Other Features</strong> <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;**Integration with Other Features**&quot;">​</a></h2><p>Notifications surface key moments from across PodSEO, including insights from <a href="/features/keyword-strategy.html">Search Visibility</a>, <a href="/features/competitive-analysis.html">Competition</a>, and <a href="/features/pulse.html">Pulse</a>. For a more comprehensive view, visit the <a href="/features/command-center.html">Command Center</a> which aggregates signals, tasks, and insights in one dashboard.</p><h2 id="choose-how-alerts-reach-you" tabindex="-1">Choose how alerts reach you <a class="header-anchor" href="#choose-how-alerts-reach-you" aria-label="Permalink to &quot;Choose how alerts reach you&quot;">​</a></h2><p>Open <strong>Settings → Notifications</strong>. Each notification type has separate controls for <strong>In-app</strong>, <strong>Email</strong>, and <strong>Browser</strong> where that delivery channel is supported. A dash means that channel is not available for that type.</p><ol><li>Find the type of event you want to adjust.</li><li>Toggle in-app or browser delivery independently.</li><li>For emails that support digests, choose <strong>As it happens</strong>, <strong>Daily digest</strong>, <strong>Weekly digest</strong>, or <strong>Never</strong>. Other email types have an on/off switch.</li><li>Check that the setting saved before leaving the page.</li></ol><p>If you haven&#39;t changed a setting, most notification types are emailed in your <strong>Weekly digest</strong>. A few arrive right away by default because they&#39;re time-sensitive: announcements, social post results, social account reconnect alerts, and podcast health alerts. New-episode insights default to the <strong>Daily digest</strong> so you get them while the episode is fresh.</p><p>Turning off email for an event does not turn off its in-app alerts. Digests combine updates on the selected cadence; use immediate delivery for events you want to act on quickly. Browser delivery also depends on your browser allowing PodSEO notifications.</p><h2 id="troubleshoot-a-missing-notification" tabindex="-1">Troubleshoot a missing notification <a class="header-anchor" href="#troubleshoot-a-missing-notification" aria-label="Permalink to &quot;Troubleshoot a missing notification&quot;">​</a></h2><p>Check the event&#39;s delivery settings, your browser permission, and your email spam folder. A daily or weekly digest will not arrive immediately. Features still follow your plan&#39;s access rules, and the absence of an alert does not prove that a ranking or placement has not changed—open its feature page to inspect the available data.</p>',31)])])}const p=t(s,[["render",n]]);export{u as __pageData,p as default};
